#!/bin/sh
# Fetches MPVKit 1.0.0's LGPL xcframeworks (checksums from its Package.swift) into Frameworks/.
# SwiftPM's own binary download stalls here, and it would fetch the GPL set too.
set -eu
cd "$(dirname "$0")"
mkdir -p Frameworks
fetch() {
  [ -d "Frameworks/$1.xcframework" ] && return 0
  tmp="Frameworks/$1.zip"
  curl -fsSL --retry 5 --retry-all-errors --retry-delay 2 -o "$tmp" "$2" || { rm -f "$tmp"; return 1; }
  sum=$(shasum -a 256 "$tmp" | cut -d' ' -f1)
  [ "$sum" = "$3" ] || { echo "$1: checksum mismatch" >&2; rm -f "$tmp"; return 1; }
  unzip -qo "$tmp" -d Frameworks && rm -f "$tmp"
}
# Four at a time: twenty at once runs a CI Mac out of network buffers. Anything
# that still failed is fetched again one by one.
throttle() { while [ "$(jobs -p | wc -l)" -ge 4 ]; do sleep 0.2; done; }
